#include <glm/glm.hpp>

struct Particle {
    glm::vec3 position, velocity, acceleration, force;
    float density;
    float pressure;
    uint16_t hash;
};

void integrateVelocity(Particle* p, float deltaTime, float g) {
    p->velocity += (p->acceleration + glm::vec3(0.0f, g, 0.0f)) * deltaTime;
}

struct Particle {
    struct Vec3 { float x, y, z; };
    Vec3 position, velocity, acceleration, force;
    float density;
    float pressure;
    uint16_t hash;
};

void integrateVelocity(Particle* p, float deltaTime, float g) {
    p->velocity.y += (p->acceleration.y + g) * deltaTime;
    p->velocity.x += p->acceleration.x * deltaTime;
    p->velocity.z += p->acceleration.z * deltaTime;
}

struct Particle {
    float position[3];
    float velocity[3];
    float acceleration[3];
    float force[3];
    float density;
    float pressure;
    uint16_t hash;
};

void integrateVelocity(Particle* p, float deltaTime, float g) {
    p->velocity[0] += p->acceleration[0] * deltaTime;
    p->velocity[1] += (p->acceleration[1] + g) * deltaTime;
    p->velocity[2] += p->acceleration[2] * deltaTime;
}
